INSERT INTO public.holiday_credit_policies VALUES
	('company_holiday_work_leave', '振休（祝日勤務特別休暇）', 1.0, 1, 'end_of_month', NULL, true, '会社独自の特別休暇。祝日の勤務自体の賃金（時間外・休日の割増）は勤怠計算どおり支払う', NULL, '2026-10-20 14:46:31.402446+00', 240),
	('substitute_holiday', '振替休日（法定）', 1.0, 1, 'none', NULL, false, '事前に休日と労働日を入れ替える制度。休日労働の割増は不要（週40時間超は時間外）', NULL, '2026-10-20 14:46:31.402446+00', 240),
	('compensatory_day_off', '代休（休日出勤）', 1.0, 1, 'one_month', NULL, true, '休日出勤の後に休ませる制度。休日出勤の割増賃金は代休を取っても必要（勤怠計算どおり支払う）', NULL, '2026-10-20 14:46:31.402446+00', 240),
	('migration', '移行（取込時の振休・代休の残り）', 1.0, 1, 'none', NULL, false, '以前の管理表から取り込んだ残り。期限は取込時に本部が指定', NULL, '2026-10-20 14:46:31.507317+00', 240) ON CONFLICT DO NOTHING;
